const body = $input.item.json.body || $input.item.json;

const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;
const message = value?.messages?.[0];

if (!message) {
  return [{ json: { skip: true } }];
}

const telefono = message.from;
const texto = message.text?.body || '';
const messageId = message.id;
const timestamp = message.timestamp;
const nombreContacto = value?.contacts?.[0]?.profile?.name || '';

// FIX: Deduplicación — Meta envía el mismo webhook dos veces
// Usamos static data para recordar messageIds procesados en los últimos 60s
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenMessageIds) staticData.seenMessageIds = {};

const now = Date.now();
// Limpiar entradas viejas (> 60 segundos)
Object.keys(staticData.seenMessageIds).forEach(id => {
  if (now - staticData.seenMessageIds[id] > 60000) delete staticData.seenMessageIds[id];
});

if (staticData.seenMessageIds[messageId]) {
  // Mensaje duplicado — ignorar
  return [{ json: { skip: true, skipReason: 'duplicate_messageId' } }];
}
staticData.seenMessageIds[messageId] = now;

return [{
  json: {
    telefono,
    texto,
    messageId,
    timestamp,
    nombreContacto,
    skip: false
  }
}];

const data = $input.item.json;
const records = data.records || [];
const now = new Date();
const results = [];

for (const record of records) {
  const fields = record.fields;
  const ultimaInteraccion = new Date(fields.Ultima_Actividad);
  const horasDiff = (now - ultimaInteraccion) / (1000 * 60 * 60);

  let tipoFollowup = null;
  if (horasDiff >= 72) tipoFollowup = '72h';
  else if (horasDiff >= 24) tipoFollowup = '24h';

  if (tipoFollowup) {
    results.push({
      json: {
        recordId: record.id,
        telefono: fields.Telefono,
        nombre: fields.Nombre,
        tipoFollowup,
        estado: fields.Estado
      }
    });
  }
}

return results;

const extract = $('🔧 Extraer Mensaje y Teléfono').item.json;
const ctx02 = $('▶️ 02 Contexto y Lead').item.json;
return [{ json: { ...extract, ...ctx02 } }];

const ctx = $('▶️ 03 Generador IA').first().json;
const d = ctx.datosRecolectados || {};

// Only show price if all data collected and not already sent
if (!ctx.todosRecolectados || ctx.cotizacionEnviada) {
  return [{ json: { ...ctx } }];
}

// Read precio from HTTP node result
const apiResp = $input.first().json;
const precio = apiResp?.data?.precio_total || apiResp?.precio_total || null;

const idioma = ctx.idiomaConversacion || 'español';
const nombre = d.nombre_cliente ? `, ${d.nombre_cliente.split(' ')[0]}` : '';
const tieneProteccion = d.proteccion_extra === true || d.proteccion_extra === 'true';

let mensajeFinal;
if (precio) {
  if (idioma === 'inglés') {
    mensajeFinal = `Here is your estimate${nombre}! 🎉\n\n📦 *${d.producto || 'Crate'}*\n📐 Dimensions: ${d.medidas || '—'}"\n🗓 Needed by: ${d.fecha || '—'}\n🛡 Extra protection: ${tieneProteccion ? 'Yes' : 'No'}\n\n💵 *Estimated price: $${precio} USD*\n_This is an estimate. The final price may vary after inspection._\n\nWould you like a formal quote sent to your email?`;
  } else {
    mensajeFinal = `¡Aquí está tu estimado${nombre}! 🎉\n\n📦 *${d.producto || 'Cajón'}*\n📐 Medidas: ${d.medidas || '—'}"\n🗓 Para: ${d.fecha || '—'}\n🛡 Protección extra: ${tieneProteccion ? 'Sí' : 'No'}\n\n💵 *Precio estimado: $${precio} USD*\n_Este es un estimado. El precio final puede variar luego de la inspección._\n\n¿Le gustaría que le enviemos la cotización formal a su correo?`;
  }
} else {
  mensajeFinal = ctx.mensaje;
}

return [{ json: {
  ...ctx,
  mensaje: mensajeFinal,
  mensajeRespuesta: mensajeFinal,
  cotizadorEnviado: !!precio
} }];

